mapper.select:
select t.machine_mac,t.machine_mac machineMac,t.heartbeat_time,t.heartbeat_time
heartbeatTime,t.impl_bean,t.impl_bean implBean,t.machine_id,t.machine_id machineId,t.machine_code,t.machine_code
machineCode,t.location_name,t.location_name locationName,t.location_id,t.location_id
locationId,t.status_cd,t.status_cd statusCd,t.community_id,t.community_id
communityId,t.machine_name,t.machine_name machineName,t.machine_ip,t.machine_ip machineIp,t.direction
from access_control t
where 1 =1

    and t.machine_mac= #{machineMac}


    and t.heartbeat_time= #{heartbeatTime}


    and t.impl_bean= #{implBean}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.location_name= #{locationName}


    and t.location_id= #{locationId}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.machine_name= #{machineName}


    and t.machine_ip= #{machineIp}


    and t.direction= #{direction}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update access_control t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.machine_mac= #{machineMac}


    , t.heartbeat_time= #{heartbeatTime}


    , t.impl_bean= #{implBean}


    , t.machine_code= #{machineCode}


    , t.location_name= #{locationName}


    , t.location_id= #{locationId}


    , t.community_id= #{communityId}


    , t.machine_name= #{machineName}


    , t.machine_ip= #{machineIp}


    , t.direction= #{direction}

where 1=1

    and t.machine_id= #{machineId}

mapper.select:
select count(1) count
from access_control t
where 1 =1

    and t.machine_mac= #{machineMac}


    and DATE_ADD(t.heartbeat_time, INTERVAL 2 MINUTE) < #{heartbeatTime}


    and t.impl_bean= #{implBean}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.location_name= #{locationName}


    and t.location_id= #{locationId}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.machine_name= #{machineName}


    and t.machine_ip= #{machineIp}


    and t.direction= #{direction}

select DATE_FORMAT(t.create_time,'%Y-%m-%d') createTime,count(1) totalCount
from access_control_inout t
WHERE 1=1

    and t.machine_id= #{machineId}


    and t.community_id= #{communityId}

and t.create_time > #{startTime}

group by DATE_FORMAT(t.create_time,'%Y-%m-%d')

select DATE_FORMAT(t.create_time,'%Y-%m-%d') createTime,count(1) totalCount
from access_control_log t
WHERE 1=1

    and t.machine_id= #{machineId}


    and t.community_id= #{communityId}

and t.create_time > #{startTime}

group by DATE_FORMAT(t.create_time,'%Y-%m-%d')

select DATE_FORMAT(t.create_time,'%Y-%m-%d') createTime,count(1) totalCount
from visit t
WHERE 1=1

    and t.community_id= #{communityId}

and t.create_time > #{startTime}

group by DATE_FORMAT(t.create_time,'%Y-%m-%d')
